        item_id: { type: 'string' },
      },
      required: ['item_id'],
    },
  },
  {
    name: 'item_list',
    description: 'List all items in creation order.',
    inputSchema: {
      type: 'object',
      properties: {},
    },
  },
];

const store = new Map(); // item_id -> item object
let counter = 0;

function isString(value) {
  return typeof value === 'string';
}

function textResult(obj) {
  return { content: [{ type: 'text', text: JSON.stringify(obj) }] };
}

function makeError(code, message) {
  const err = new Error(message);
  err.code = code;
  return err;
}

function validateItemFields(args) {
  const allowed = ['item_id', 'name'];
  for (const key of Object.keys(args)) {
    if (key === 'item_id') continue; // id handled separately
    if (!allowed.includes(key)) {
      throw makeError(-32602, `unknown field: ${key}`);
    }
    const value = args[key];
    if (key === 'name') {
      if (!isString(value)) {
        throw makeError(-32602, `field '${key}' must be a string`);
      }
    }
  }
}

async function item_create(args) {
  if (!args || typeof args !== 'object') {
    throw makeError(-32602, 'arguments must be an object');
  }
  if (!('name' in args)) {
    throw makeError(-32602, "missing required field: name");
  }
  validateItemFields(args);
  counter += 1;
  const id = `i${counter}`;
  const item = { item_id: id, name: args.name };
  store.set(id, item);
  return textResult(item);
}

async function item_update(args) {
  if (!args || typeof args !== 'object') {
    throw makeError(-32602, 'arguments must be an object');
  }
  if (!('item_id' in args)) {
    throw makeError(-32602, "missing required field: item_id");
  }
  validateItemFields(args);
  const id = args.item_id;
  if (!store.has(id)) {
    throw makeError(-32602, `item not found: ${id}`);
  }
  const existing = store.get(id);
  for (const key of Object.keys(args)) {
    if (key === 'item_id') continue;
    existing[key] = args[key];
  }
  return textResult(existing);
}

async function item_get(args) {
  if (!args || typeof args !== 'object') {
    throw makeError(-32602, 'arguments must be an object');
  }
  if (!('item_id' in args)) {
    throw makeError(-32602, "missing required field: item_id");
  }
  const id = args.item_id;
  if (!store.has(id)) {
    throw makeError(-32602, `item not found: ${id}`);
  }
  return textResult(store.get(id));
}

async function item_list(args) {
  return textResult([...store.values()]);
}

const handlers = {
  item_create,
  item_update,
  item_get,
  item_list,
};

export async function listTools() {
  return tools;
}

export async function callTool(name, args) {
  const handler = handlers[name];
  if (!handler) {
    throw makeError(-32601, `unknown tool: ${name}`);
  }
  return handler(args || {});
}
